<script src="https://unpkg.com/vis-network/standalone/umd/vis-network.min.js"></script>
<script>
window.initXlinkTopology = function () {
 const el = document.getElementById('xlink-topology-graph');
 if (!el || !window.vis) return;
 if (el._network) { el._network.destroy(); el._network = null; }
 const rawNodes = @json($nodes);
 const rawEdges = @json($graphEdges);
 const nodes = new vis.DataSet(rawNodes.map(n => ({
  ...n, color: n.alarm === 'critical' ? '#dc2626' : (n.alarm === 'warning' ? '#f59e0b' : (n.status === 'online' ? '#22c55e' : (n.status === 'offline' ? '#ef4444' : (n.group === 'splitter' ? '#f59e0b' : '#94a3b8')))),
  shape: n.group === 'router' ? 'box' : (n.group === 'olt' ? 'database' : (n.group === 'onu' ? 'diamond' : (n.group === 'customer' ? 'ellipse' : (n.group === 'splitter' ? 'triangle' : (n.group === 'odf' ? 'hexagon' : (n.group === 'pop' ? 'star' : (n.group === 'fiber_segment' ? 'text' : 'box'))))))),
  font: {color:'#172033', size:13}, borderWidth:1, margin:12
 })));
 const nodeAlarm=Object.fromEntries(rawNodes.map(n=>[n.id,n.alarm])); const edgeRows = rawEdges.map(e => { const u=Number(e.utilization||0); const metrics=[e.traffic_mbps!=null?e.traffic_mbps+' Mbps traffic':null,e.capacity_mbps?e.capacity_mbps+' Mbps capacity':null,e.latency_ms!=null?e.latency_ms+' ms latency':null,e.packet_loss!=null?e.packet_loss+'% loss':null].filter(Boolean).join(' · '); const alarm=nodeAlarm[e.from]==='critical'||nodeAlarm[e.to]==='critical'?'critical':(nodeAlarm[e.from]==='warning'||nodeAlarm[e.to]==='warning'?'warning':''); const color=alarm==='critical'?'#dc2626':(alarm==='warning'?'#f59e0b':(e.connection_type==='fiber_core'||e.connection_type==='splitter'?(u>=90?'#dc2626':u>=70?'#f59e0b':'#16a34a'):(e.connection_type==='uplink'?'#2563eb':'#94a3b8'))); const metric=e.utilization!==null&&e.utilization!==undefined ? ' · '+e.utilization+'%' : ''; return {...e,label:(e.label||'')+metric,title:metrics || (e.connection_type||'Connection'),color:{color,highlight:color},width:e.utilization>=90?5:e.utilization>=70?4:2,font:{size:10,align:'middle'},smooth:{type:'dynamic'},dashes:e.dashes||false}; });
 const edges = new vis.DataSet(edgeRows);
 const network = new vis.Network(el, {nodes, edges}, {
  autoResize:true, interaction:{hover:true,navigationButtons:true,keyboard:{enabled:true}},
  physics:{enabled:true, stabilization:{iterations:180}, barnesHut:{gravitationalConstant:-4500,springLength:150,springConstant:0.035}},
  edges:{arrows:{to:{enabled:true,scaleFactor:0.65}},width:2},
  groups:{router:{shape:'box'},olt:{shape:'database'},onu:{shape:'diamond'},customer:{shape:'ellipse'},splitter:{shape:'triangle'},olt_pon:{shape:'dot'},odf:{shape:'hexagon'},rack:{shape:'box'},pop:{shape:'star'},fiber_segment:{shape:'text'}}
 });
 el._network = network;
 window.xlinkTopologyNetwork = network;
 const graphCard = el.closest('.nt-card');
 const fullBtn = document.getElementById('xlink-fullscreen');
 const weatherBtn = document.getElementById('xlink-weathermap');
 fullBtn?.addEventListener('click', () => {
   if (!graphCard) return;
   if (!document.fullscreenElement) graphCard.requestFullscreen?.();
   else document.exitFullscreen?.();
 });
 weatherBtn?.addEventListener('click', () => {
   const active = weatherBtn.dataset.active === '1';
   weatherBtn.dataset.active = active ? '0' : '1';
   weatherBtn.textContent = active ? 'WeatherMap' : 'WeatherMap ON';
   network.setOptions({physics:{enabled:!active, stabilization:{iterations:120}}, interaction:{hover:true,navigationButtons:true,keyboard:{enabled:true}}});
   edgeRows.forEach(e => { if ((e.traffic_mbps||0)>0) { e.dashes=true; e.width=active?2:(Number(e.utilization||0)>=90?6:Number(e.utilization||0)>=70?5:3); }});
   edges.update(edgeRows);
 });
 const popFilter = document.getElementById('xlink-pop-filter');
 popFilter?.addEventListener('change', () => {
  const selected = popFilter.value;
  if (!selected) { nodes.update(rawNodes.map(n=>({id:n.id,hidden:false}))); edges.update(edgeRows.map(e=>({id:e.id,hidden:false}))); return; }
  const connected = new Set([selected]); const queue=[selected];
  while(queue.length){ const k=queue.shift(); edgeRows.forEach(e=>{ if(e.from===k && !connected.has(e.to)){connected.add(e.to);queue.push(e.to);} if(e.to===k && !connected.has(e.from)){connected.add(e.from);queue.push(e.from);} }); }
  nodes.update(rawNodes.map(n=>({id:n.id,hidden:!connected.has(n.id)})));
  edges.update(edgeRows.map(e=>({id:e.id,hidden:!(connected.has(e.from)&&connected.has(e.to))})));
 });
 const filterRoot = document.getElementById('xlink-topology-filters');
 filterRoot?.querySelectorAll('[data-status-filter]').forEach(button => button.addEventListener('click', () => {
  const wanted = button.dataset.statusFilter || 'all';
  filterRoot.querySelectorAll('[data-status-filter]').forEach(b => b.classList.toggle('active', b === button));
  const visible = new Set(rawNodes.filter(n => wanted === 'all' || n.status === wanted).map(n => n.id));
  nodes.update(rawNodes.map(n => ({id:n.id, hidden: !visible.has(n.id)})));
  edges.update(edgeRows.map(e => ({id:e.id, hidden: !(visible.has(e.from) && visible.has(e.to))})));
 }));
 window.addEventListener('xlink-topology-trace', function(event) {
 const path=event.detail?.path||[]; const box=document.getElementById('xlink-trace-path'); const summary=document.getElementById('xlink-trace-summary');
 if(!box) return; summary.textContent=path.length ? path.length+' topology nodes traced' : 'No path found';
 box.innerHTML=path.length ? path.map((n,i)=>`<div class="border rounded-3 px-3 py-2 bg-light"><strong>${i+1}. ${String(n.label||n.key).replace(/</g,'&lt;')}</strong>${n.port?`<div class="small text-muted">Port ${String(n.port).replace(/</g,'&lt;')}</div>`:''}</div>${i<path.length-1?'<span class="text-primary fw-bold">→</span>':''}`).join('') : '<span class="text-muted">No path found.</span>';
 document.getElementById('xlink-trace-panel')?.scrollIntoView({behavior:'smooth',block:'center'});
 if(window.xlinkTopologyNetwork){ const ids=path.map(n=>n.key); const edgeIds=path.map(n=>n.edge).filter(Boolean); const nd=window.xlinkTopologyNetwork.body.data.nodes; const ed=window.xlinkTopologyNetwork.body.data.edges; const allN=nd.get(); nd.update(allN.map(n=>({...n,color: n._baseColor || n.color, opacity: ids.includes(n.id)?1:.28, borderWidth:ids.includes(n.id)?3:1}))); const allE=ed.get(); ed.update(allE.map(e=>({...e,width:edgeIds.includes(e.id)?6:(e._baseWidth||2), opacity:edgeIds.includes(e.id)?1:.18}))); }
});
window.addEventListener('xlink-topology-locate', function(event){ const box=document.getElementById('xlink-topology-search-result'); if(box) box.textContent=event.detail?.found===false?'No matching topology node found.':''; });
const locateBtn=document.getElementById('xlink-topology-locate'); const searchBox=document.getElementById('xlink-topology-search'); locateBtn?.addEventListener('click',()=>{ const q=searchBox?.value?.trim(); if(q) Livewire.dispatch('locateTopology',{query:q}); }); searchBox?.addEventListener('keydown',e=>{if(e.key==='Enter') locateBtn?.click();});

network.on('click', function(params) {
  if (!params.nodes.length) return;
  const node = nodes.get(params.nodes[0]);
  if (!node) return;
  const detail = document.getElementById('xlink-node-detail');
  const body = document.getElementById('xlink-node-detail-body');
  if (!detail || !body) return;
  const connected = edgeRows.filter(e => e.from === node.id || e.to === node.id);
  const esc = value => String(value ?? '—').replace(/</g,'&lt;');
  const metrics = connected.map(e => {
    const side = e.from === node.id ? 'OUT' : 'IN';
    const peer = e.from === node.id ? e.to : e.from;
    const util = e.utilization != null ? e.utilization + '%' : '—';
    return '<div class="border rounded-3 p-2 mb-2"><div class="d-flex justify-content-between"><strong>'+side+' · '+esc(String(e.connection_type || 'link').replace(/_/g,' '))+'</strong><span class="badge bg-light text-dark border">'+util+'</span></div><div class="small text-muted">'+esc(peer)+' · '+esc(e.source_port || e.target_port || 'No port')+'</div><div class="small">'+(e.traffic_mbps != null ? e.traffic_mbps+' Mbps traffic · ' : '')+(e.capacity_mbps ? e.capacity_mbps+' Mbps capacity · ' : '')+(e.latency_ms != null ? e.latency_ms+' ms latency · ' : '')+(e.packet_loss != null ? e.packet_loss+'% loss' : '')+'</div></div>';
  }).join('');
  body.innerHTML = '<div class="row g-3"><div class="col-md-4"><div class="nt-muted">Node</div><strong>'+esc(node.label)+'</strong><div class="small text-muted">'+esc(node.group)+'</div></div><div class="col-md-2"><div class="nt-muted">Status</div><span class="badge '+(node.status==='online'?'bg-success':node.status==='offline'?'bg-danger':'bg-secondary')+'">'+esc(node.status || 'unknown')+'</span></div><div class="col-md-2"><div class="nt-muted">Alarm</div><span class="badge '+(node.alarm==='critical'?'bg-danger':node.alarm==='warning'?'bg-warning text-dark':'bg-success')+'">'+esc(node.alarm || 'online')+'</span></div><div class="col-md-4"><div class="nt-muted">Info</div><span class="small">'+esc(node.title || '')+'</span></div></div><hr><strong>Connected Links ('+connected.length+')</strong><div class="mt-2">'+(metrics || '<span class="text-muted">No connected links.</span>')+'</div>'+(node.url ? '<a class="btn btn-sm btn-outline-primary mt-2" href="'+node.url+'">Open Device / Mapping</a>' : '');
  detail.classList.remove('d-none');
  detail.scrollIntoView({behavior:'smooth',block:'nearest'});
 });
document.getElementById('xlink-node-detail-close')?.addEventListener('click',()=>document.getElementById('xlink-node-detail')?.classList.add('d-none'));
 // WeatherMap-style traffic pulse: active links periodically animate their dash offset.
 let pulse=0;
 const pulseTimer=setInterval(()=>{ if(!el._network) return; pulse=(pulse+1)%20; edgeRows.forEach(e=>{ const u=Number(e.utilization||0); if((e.traffic_mbps||0)>0){ e.dashes=true; e.dashOffset=pulse; e.width=u>=90?6:u>=70?5:3; } else { e.dashes=e.dashes||false; }}); edges.update(edgeRows); }, 700);
 el._pulseTimer=pulseTimer;
 @if($mode==='live')
 const sync=document.getElementById('xlink-topology-sync'); sync?.addEventListener('click',()=>{ sync.disabled=true; sync.innerText='Syncing…'; @this.$refresh().then(()=>{ setTimeout(()=>{ sync.disabled=false; sync.innerHTML='<i class=\"bi bi-lightning-charge me-1\"></i>Sync Live'; window.initXlinkTopology?.(); },200); }); });
const refresh=document.getElementById('xlink-topology-refresh');
 refresh?.addEventListener('click',()=>{ const state=document.getElementById('xlink-topology-live-state'); if(state) state.textContent='REFRESHING…'; @this.$refresh().then(()=>{ setTimeout(()=>window.initXlinkTopology?.(),150); }); });
 if(!window.xlinkTopologyAutoRefresh) window.xlinkTopologyAutoRefresh=setInterval(()=>{ const state=document.getElementById('xlink-topology-live-state'); if(state) state.textContent='SYNC…'; @this.$refresh().then(()=>{ setTimeout(()=>{ if(state) state.textContent='LIVE'; window.initXlinkTopology?.(); },150); }); },30000);
 @endif
};
document.addEventListener('livewire:navigated', () => window.initXlinkTopology?.());
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => window.initXlinkTopology?.()); else window.initXlinkTopology?.();
</script>
</div>
